def design(m):
    z=pd.DataFrame(index=m.index)
    for c in ['sex','library_prep','site_id']:
        d=pd.get_dummies(m[c].fillna('missing'),prefix=c,drop_first=True,dtype=float); z=z.join(d)
    z['duration']=m.disease_duration.astype(float); z['rin']=m.rin.astype(float); z['rin2']=z.rin**2; z['pct_mrna_bases']=m.pct_mrna_bases.astype(float)
    for c in ['gPC1','gPC2','gPC3','gPC4','gPC5']: z[c]=pd.to_numeric(m[c],errors='coerce')
    z=sm.add_constant(z.astype(float)); return z

def run(t):
    base=f'data/{t}_Spinal_Cord_'; m=pd.read_csv(base+'metadata.tsv.gz',sep='\t'); m=m[(m.disease=='ALS')&m.disease_duration.notna()].copy(); m=m.dropna(subset=['sex','rin','pct_mrna_bases','library_prep','site_id','gPC1','gPC2','gPC3','gPC4','gPC5'])
    c=pd.read_csv(base+'gene_counts.tsv.gz',sep='\t'); e0=pd.read_csv(base+'gene_tpm.tsv.gz',sep='\t'); gm=pd.read_csv('data/gencode.v30.gene_meta.tsv.gz',sep='\t'); gm['geneid']=gm.geneid.str.replace(r'\\.\\d+$','',regex=True); gmap=gm.drop_duplicates('geneid').set_index('geneid').genename; names=e0.set_index('ensembl_id')['gene_name'].groupby(level=0).first(); names=names.combine_first(names.index.to_series().map(gmap)); e=e0; ids=m.rna_id.tolist(); cols=[x for x in ids if x in c.columns]; m=m.set_index('rna_id').loc[cols]; c=c.set_index('ensembl_id')[cols]; e=e.set_index('ensembl_id')[cols]; c=c.drop(columns=['gene_name'],errors='ignore'); e=e.drop(columns=['gene_name'],errors='ignore')
    # requested TPM filter: >=1 TPM in at least 20% of ALS samples
    keep=(e>=1).sum(axis=1)>=max(3,int(.2*len(cols))); c=c.loc[keep]; e=e.loc[keep]
